(()=>{'use strict';const search=document.querySelector('#search'),group=document.querySelector('#group'),kind=document.querySelector('#kind'),cards=[...document.querySelectorAll('.card')];const language=document.documentElement.lang;function filter(){const q=search.value.trim().toLocaleLowerCase(language);let n=0;for(const c of cards){const show=c.textContent.toLocaleLowerCase(language).includes(q)&&(group.value==='all'||c.dataset.group===group.value)&&(kind.value==='all'||c.dataset.kind===kind.value);c.hidden=!show;if(show)n++;}document.querySelector('#results').textContent=`${n} / ${cards.length}`;document.querySelector('#empty').hidden=n>0;}[search,group,kind].forEach(x=>x.addEventListener('input',filter));filter();})();
